import{_ as e,c as a,o as l,a3 as r,j as n,aB as o,aC as i}from"./chunks/framework.MI-M1z4O.js";const f=JSON.parse('{"title":"コレクション管理および一括実行","description":"複数の単体シナリオをまとめて順次または並列で一括実行するSyncETAコレクションの構成ガイドです。","frontmatter":{"title":"コレクション管理および一括実行","description":"複数の単体シナリオをまとめて順次または並列で一括実行するSyncETAコレクションの構成ガイドです。","head":[["meta",{"name":"keywords","content":"SyncETA, コレクション, 一括実行, クロスブラウジング, シナリオ一括実行, テストスイート"}],["meta",{"property":"og:title","content":"コレクション管理および一括実行 | SyncETA"}],["meta",{"property":"og:description","content":"単体シナリオをグループ化して順次または並列で実行するコレクション管理ガイドです。"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/synceta/collection"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synceta/collection"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synceta/collection"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synceta/collection"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synceta/collection"}]],"sort":500},"headers":[],"relativePath":"ja/synceta/collection.md","filePath":"ja/synceta/collection.md","lastUpdated":1795293539000}'),s={name:"ja/synceta/collection.md"};function c(d,t,h,p,g,m){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="コレクション管理および一括実行" tabindex="-1">コレクション管理および一括実行 <a class="header-anchor" href="#コレクション管理および一括実行" aria-label="Permalink to “コレクション管理および一括実行”">​</a></h1><p><strong>「コレクション（Collection）」</strong> は、関連する複数のテストシナリオをグループ化し、1つのテストスイート（Test Suite）単位で管理・一括実行する機能です。</p><hr><h2 id="_1-コレクションの主な用途" tabindex="-1">1. コレクションの主な用途 <a class="header-anchor" href="#_1-コレクションの主な用途" aria-label="Permalink to “1. コレクションの主な用途”">​</a></h2><ul><li><strong>エンドツーエンドシナリオの一括順次実行</strong>：ログイン -&gt; 商品検索 -&gt; 注文決済 -&gt; 注文キャンセルのような個別シナリオを連続して順次検証します。</li><li><strong>マルチブラウザ同時並列実行</strong>：同一のシナリオセットをChrome、Firefox、Edgeなど複数のブラウザ環境で同時に並列駆動し、クロスブラウジング互換性を点検します。</li></ul><hr><h2 id="_2-コレクション作成手順" tabindex="-1">2. コレクション作成手順 <a class="header-anchor" href="#_2-コレクション作成手順" aria-label="Permalink to “2. コレクション作成手順”">​</a></h2><h3 id="ステップ1-コレクションメニューへの移動および新規作成" tabindex="-1">ステップ1：コレクションメニューへの移動および新規作成 <a class="header-anchor" href="#ステップ1-コレクションメニューへの移動および新規作成" aria-label="Permalink to “ステップ1：コレクションメニューへの移動および新規作成”">​</a></h3><p>左メニューの <strong>「コレクション」</strong> へ移動し、右上の <strong>「新しいコレクション」</strong> ボタンをクリックします。</p><p><img src="'+o+'" alt="コレクション作成メニュー" loading="lazy"></p><h3 id="ステップ2-含めるシナリオおよび実行順序の選択" tabindex="-1">ステップ2：含めるシナリオおよび実行順序の選択 <a class="header-anchor" href="#ステップ2-含めるシナリオおよび実行順序の選択" aria-label="Permalink to “ステップ2：含めるシナリオおよび実行順序の選択”">​</a></h3><p>コレクションに含めるシナリオ一覧にチェックを入れ、ドラッグ＆ドロップによって実行順序を構成します。</p><p><img src="'+i+'" alt="シナリオ選択および順序指定" loading="lazy"></p><hr><h2 id="_3-コレクション実行モードおよび戦略の比較" tabindex="-1">3. コレクション実行モードおよび戦略の比較 <a class="header-anchor" href="#_3-コレクション実行モードおよび戦略の比較" aria-label="Permalink to “3. コレクション実行モードおよび戦略の比較”">​</a></h2><p>コレクションは、テスト目的やCI/CDパイプラインの段階に応じて2つの実行モードを選択して駆動できます。</p><table tabindex="0"><thead><tr><th style="text-align:left;">実行モード</th><th style="text-align:left;">動作方式</th><th style="text-align:center;">セッションおよびCookieの共有可否</th><th style="text-align:left;">主な活用シナリオ</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>順次実行（Sequential Mode）</strong></td><td style="text-align:left;">指定された順序（<code>1 -&gt; 2 -&gt; 3</code>）でシナリオを1つずつ実行</td><td style="text-align:center;">分離または選択的維持</td><td style="text-align:left;">スモークテスト（Smoke Test）、前後データ依存関係のある業務検証</td></tr><tr><td style="text-align:left;"><strong>並列実行（Parallel Mode）</strong></td><td style="text-align:left;">多数のPlaywrightブラウザワーカーでシナリオおよびマルチブラウザ（<code>Chromium</code>、<code>Firefox</code>、<code>WebKit</code>）を同時駆動</td><td style="text-align:center;">シナリオごとに完全分離</td><td style="text-align:left;">大規模夜間回帰テスト（Nightly Regression）、クロスブラウジング互換性検証</td></tr></tbody></table><hr><h2 id="_4-コレクション実行および結果集計" tabindex="-1">4. コレクション実行および結果集計 <a class="header-anchor" href="#_4-コレクション実行および結果集計" aria-label="Permalink to “4. コレクション実行および結果集計”">​</a></h2><p>コレクション実行時、各シナリオ別の成功/失敗ステータスがリアルタイムで集計され、コレクション全体の実行完了後に総合結果レポートがダッシュボードに記録されます。</p>',20),n("iframe",{width:"100%",height:"400",src:"https://www.youtube.com/embed/dsb0XpGy7A0",frameborder:"0",allowfullscreen:"",allow:"autoplay; encrypted-media"},null,-1)])])}const _=e(s,[["render",c]]);export{f as __pageData,_ as default};
